-- RRC086: MariaDB10.11, dedicated fresh admin session; manual coordinated application only.
-- Source recipe facts/provenance: batch.public.json. No engine/updater/version/rule changes.
-- Anonymous compound block: no permanent helper procedure or migration table.
DELIMITER //
BEGIN NOT ATOMIC
 DECLARE own_transaction BOOLEAN DEFAULT FALSE;
 DECLARE already_present INT DEFAULT 0;
 DECLARE recipes_before BIGINT DEFAULT 0;
 DECLARE entries_before BIGINT DEFAULT 0;
 DECLARE EXIT HANDLER FOR SQLEXCEPTION
 BEGIN
  IF own_transaction THEN ROLLBACK; END IF;
  RESIGNAL;
 END;
 IF @@in_transaction <> 0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC086 requires fresh transaction-free session'; END IF;
 IF FIND_IN_SET('STRICT_ALL_TABLES',@@SESSION.sql_mode)=0 AND FIND_IN_SET('STRICT_TRANS_TABLES',@@SESSION.sql_mode)=0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC086 strict SQL mode required'; END IF;
 IF (SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('tradeskill_recipe','tradeskill_recipe_entries','items') AND ENGINE='InnoDB')<>3 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC086 InnoDB foundation mismatch'; END IF;
 IF (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tradeskill_recipe')<>16 OR (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tradeskill_recipe_entries')<>8 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC086 recipe schema column-count mismatch'; END IF;
 CREATE TEMPORARY TABLE rrc086_recipes LIKE tradeskill_recipe;
 CREATE TEMPORARY TABLE rrc086_entries LIKE tradeskill_recipe_entries;
 CREATE TEMPORARY TABLE rrc086_items(id INT PRIMARY KEY,name VARCHAR(64) NOT NULL) ENGINE=InnoDB;
 START TRANSACTION;
 SET own_transaction=TRUE;
 SELECT COUNT(*) INTO recipes_before FROM tradeskill_recipe;
 SELECT COUNT(*) INTO entries_before FROM tradeskill_recipe_entries;
 SELECT COUNT(*) INTO already_present FROM tradeskill_recipe r JOIN rrc086_recipes e ON r.id=e.id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM rrc086_items e LEFT JOIN items i ON i.id=e.id WHERE i.id IS NULL OR BINARY i.Name<>BINARY e.name) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC086 item identity/dependency mismatch'; END IF;
 IF (SELECT COUNT(*) FROM items WHERE id=93492 AND itemclass=1 AND bagtype=11 AND bagslots=10 AND bagsize=3 AND classes=15360)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC086 native kit mismatch'; END IF; IF (SELECT COUNT(*) FROM items WHERE (id=115455 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=4128) OR (id=93545 AND size=0 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=90309 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=93587 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=93564 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=93578 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=93539 AND size=0 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=93515 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=115660 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=4608) OR (id=93555 AND size=0 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=93560 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=93559 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=93558 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=93562 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=90307 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=115663 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=4096) OR (id=93542 AND size=0 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=93553 AND size=0 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=115666 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=4096) OR (id=93557 AND size=0 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=93572 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=90310 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=115669 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=4096) OR (id=93579 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=93573 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=115673 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=4096) OR (id=93537 AND size=0 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=115676 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=4096) OR (id=90308 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=115682 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=4096) OR (id=93548 AND size=0 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=115687 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=4096) OR (id=93574 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=115691 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=4096) OR (id=115695 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=4096) OR (id=115698 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=4096) OR (id=93580 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=115701 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=4096) OR (id=93577 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=93565 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=115704 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=4096) OR (id=115707 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=4096) OR (id=93549 AND size=0 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=93563 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=93582 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=115716 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=4096) OR (id=93554 AND size=0 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=115719 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=4096) OR (id=115723 AND size=1 AND stackable=0 AND maxcharges=0 AND classes=4096) OR (id=90311 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=115732 AND size=1 AND stackable=0 AND maxcharges=0 AND classes=4096) OR (id=115739 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=4096) OR (id=93546 AND size=0 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=115753 AND size=1 AND stackable=0 AND maxcharges=0 AND classes=4096) OR (id=115773 AND size=1 AND stackable=0 AND maxcharges=0 AND classes=4096) OR (id=115779 AND size=1 AND stackable=0 AND maxcharges=0 AND classes=4096) OR (id=115905 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=5120) OR (id=93526 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360))<>58 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC086 input/output semantics mismatch'; END IF; IF (SELECT COUNT(*) FROM items WHERE (id=115455 AND itemtype=20 AND scrolleffect=14455 AND scrolllevel=0 AND reqlevel=0) OR (id=115660 AND itemtype=20 AND scrolleffect=14660 AND scrolllevel=0 AND reqlevel=0) OR (id=115663 AND itemtype=20 AND scrolleffect=14663 AND scrolllevel=0 AND reqlevel=0) OR (id=115666 AND itemtype=20 AND scrolleffect=14666 AND scrolllevel=0 AND reqlevel=0) OR (id=115669 AND itemtype=20 AND scrolleffect=14669 AND scrolllevel=0 AND reqlevel=0) OR (id=115673 AND itemtype=20 AND scrolleffect=14673 AND scrolllevel=0 AND reqlevel=0) OR (id=115676 AND itemtype=20 AND scrolleffect=14676 AND scrolllevel=0 AND reqlevel=0) OR (id=115682 AND itemtype=20 AND scrolleffect=14682 AND scrolllevel=0 AND reqlevel=0) OR (id=115687 AND itemtype=20 AND scrolleffect=14687 AND scrolllevel=0 AND reqlevel=0) OR (id=115691 AND itemtype=20 AND scrolleffect=14691 AND scrolllevel=0 AND reqlevel=0) OR (id=115695 AND itemtype=20 AND scrolleffect=14695 AND scrolllevel=0 AND reqlevel=0) OR (id=115698 AND itemtype=20 AND scrolleffect=14698 AND scrolllevel=0 AND reqlevel=0) OR (id=115701 AND itemtype=20 AND scrolleffect=14701 AND scrolllevel=0 AND reqlevel=0) OR (id=115704 AND itemtype=20 AND scrolleffect=14704 AND scrolllevel=0 AND reqlevel=0) OR (id=115707 AND itemtype=20 AND scrolleffect=14707 AND scrolllevel=0 AND reqlevel=0) OR (id=115716 AND itemtype=20 AND scrolleffect=14716 AND scrolllevel=0 AND reqlevel=0) OR (id=115719 AND itemtype=20 AND scrolleffect=14719 AND scrolllevel=0 AND reqlevel=0) OR (id=115723 AND itemtype=20 AND scrolleffect=14723 AND scrolllevel=0 AND reqlevel=0) OR (id=115732 AND itemtype=20 AND scrolleffect=14732 AND scrolllevel=0 AND reqlevel=0) OR (id=115739 AND itemtype=20 AND scrolleffect=14739 AND scrolllevel=0 AND reqlevel=0) OR (id=115753 AND itemtype=20 AND scrolleffect=14753 AND scrolllevel=0 AND reqlevel=0) OR (id=115773 AND itemtype=20 AND scrolleffect=14773 AND scrolllevel=0 AND reqlevel=0) OR (id=115779 AND itemtype=20 AND scrolleffect=14779 AND scrolllevel=0 AND reqlevel=0) OR (id=115905 AND itemtype=20 AND scrolleffect=14905 AND scrolllevel=0 AND reqlevel=0))<>24 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC086 Tome spell binding mismatch'; END IF;
 IF already_present<>24 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC086 rollback requires exact whole installed batch'; END IF;
 IF EXISTS(SELECT 1 FROM rrc086_recipes e LEFT JOIN tradeskill_recipe r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND r.`name` <=> e.`name` AND r.`tradeskill` <=> e.`tradeskill` AND r.`skillneeded` <=> e.`skillneeded` AND r.`trivial` <=> e.`trivial` AND r.`nofail` <=> e.`nofail` AND r.`replace_container` <=> e.`replace_container` AND r.`notes` <=> e.`notes` AND r.`must_learn` <=> e.`must_learn` AND r.`learned_by_item_id` <=> e.`learned_by_item_id` AND r.`quest` <=> e.`quest` AND r.`enabled` <=> e.`enabled` AND r.`min_expansion` <=> e.`min_expansion` AND r.`max_expansion` <=> e.`max_expansion` AND r.`content_flags` <=> e.`content_flags` AND r.`content_flags_disabled` <=> e.`content_flags_disabled`)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC086 recipe postimage mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM rrc086_entries e LEFT JOIN tradeskill_recipe_entries r ON r.`recipe_id` <=> e.`recipe_id` AND r.`item_id` <=> e.`item_id` AND r.`successcount` <=> e.`successcount` AND r.`failcount` <=> e.`failcount` AND r.`componentcount` <=> e.`componentcount` AND r.`salvagecount` <=> e.`salvagecount` AND r.`iscontainer` <=> e.`iscontainer` WHERE r.id IS NULL) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC086 expected entry absent'; END IF;
 IF EXISTS(SELECT 1 FROM tradeskill_recipe_entries r JOIN rrc086_recipes q ON q.id=r.recipe_id LEFT JOIN rrc086_entries e ON r.`recipe_id` <=> e.`recipe_id` AND r.`item_id` <=> e.`item_id` AND r.`successcount` <=> e.`successcount` AND r.`failcount` <=> e.`failcount` AND r.`componentcount` <=> e.`componentcount` AND r.`salvagecount` <=> e.`salvagecount` AND r.`iscontainer` <=> e.`iscontainer` WHERE e.id IS NULL) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC086 foreign/different target entries'; END IF;
 IF (SELECT COUNT(*) FROM tradeskill_recipe_entries r JOIN rrc086_recipes q ON q.id=r.recipe_id)<>188 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC086 target entry multiplicity mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM char_recipe_list c JOIN rrc086_recipes e ON c.recipe_id=e.id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC086 rollback refused: learned recipe references exist'; END IF;
 DELETE r FROM tradeskill_recipe_entries r JOIN rrc086_recipes e ON r.recipe_id=e.id;
 DELETE r FROM tradeskill_recipe r JOIN rrc086_recipes e ON r.id=e.id;
 IF (SELECT COUNT(*) FROM tradeskill_recipe)<>recipes_before-24 OR (SELECT COUNT(*) FROM tradeskill_recipe_entries)<>entries_before-188 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC086 rollback count mismatch'; END IF;
 DROP TEMPORARY TABLE rrc086_entries;
 DROP TEMPORARY TABLE rrc086_recipes;
 DROP TEMPORARY TABLE rrc086_items;
 COMMIT;
 SET own_transaction=FALSE;
 SELECT 'RRC086' AS batch,already_present AS previous_recipe_count,recipes_before AS recipes_before,(SELECT COUNT(*) FROM tradeskill_recipe) AS recipes_after,entries_before AS entries_before,(SELECT COUNT(*) FROM tradeskill_recipe_entries) AS entries_after,@@in_transaction AS in_transaction;
END//
DELIMITER ;
